   127→                        <span class="badge" style="background:${color}22;color:${color};text-transform:capitalize">${a.jenis}</span>
   128→                        ${a.is_pinned ? '<i class="bi bi-pin-fill text-warning" title="Disematkan"></i>' : ''}
   129→                    </div>
   130→                    <span class="badge ${a.status==='aktif'?'bg-success':a.status==='draft'?'bg-warning text-dark':'bg-secondary'}">${a.status}</span>
   131→                </div>
   132→                <h6 class="fw-bold mb-2">${a.judul}</h6>
   133→                <p class="text-muted mb-3" style="font-size:12px;line-height:1.5">${a.konten.substring(0,100)}${a.konten.length>100?'...':''}</p>
   134→                <div class="d-flex justify-content-between align-items-center">
   135→                    <small class="text-muted"><i class="bi bi-people me-1"></i>${a.target==='semua'?'Semua':a.target}</small>
   136→                    <div class="d-flex gap-1">
   137→                        <button onclick="editAnn(${a.id})" class="btn btn-sm btn-outline-primary"><i class="bi bi-pencil"></i></button>
   138→                        <button onclick="deleteAnn(${a.id},'${a.judul}')" class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button>
   139→                    </div>
   140→                </div>
   141→                <div class="mt-2 pt-2 border-top" style="font-size:11px;color:var(--text-muted)">
   142→                    ${a.tanggal_mulai ? '<i class="bi bi-calendar me-1"></i>'+a.tanggal_mulai : ''}
   143→                    ${a.tanggal_mulai && a.tanggal_selesai ? ' – '+a.tanggal_selesai : ''}
   144→                </div>
