   149→
   150→function renderPagination(data) {
   151→    const el = document.getElementById('paginationLinks');
   152→    if (data.last_page <= 1) { el.innerHTML=''; return; }
   153→    let h = '<nav><ul class="pagination pagination-sm mb-0">';
   154→    h += `<li class="page-item ${data.current_page==1?'disabled':''}"><a class="page-link" href="#" onclick="loadData(${data.current_page-1});return false">‹</a></li>`;
   155→    for(let i=1;i<=data.last_page;i++) h += `<li class="page-item ${i==data.current_page?'active':''}"><a class="page-link" href="#" onclick="loadData(${i});return false">${i}</a></li>`;
   156→    h += `<li class="page-item ${data.current_page==data.last_page?'disabled':''}"><a class="page-link" href="#" onclick="loadData(${data.current_page+1});return false">›</a></li></ul></nav>`;
