   172→function loadMessages(roomId) {
   173→    fetch(`{{ url('admin/messages') }}/${roomId}/messages`, { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
   174→        .then(r => r.json()).then(res => {
   175→            const myId = {{ auth()->id() }};
   176→            const el = document.getElementById('chatMessages');
   177→            if (!res.data.length) { el.innerHTML = '<div class="text-center text-muted" style="font-size:13px;padding:30px 0">Mulai percakapan!</div>'; return; }
   178→            el.innerHTML = res.data.map(m => {
