   180→                return `<div class="d-flex ${isMine?'justify-content-end':'justify-content-start'}">
   181→                    <div style="max-width:70%">
   182→                        ${!isMine ? `<div style="font-size:11px;font-weight:600;color:#c84ddf;margin-bottom:3px">${m.pengirim?.name||'User'}</div>` : ''}
   183→                        <div style="background:${isMine?'linear-gradient(135deg,#c84ddf,#7c3aed)':'var(--card-bg)'};color:${isMine?'white':'var(--text-primary)'};border:${isMine?'none':'1px solid var(--card-border)'};padding:10px 14px;border-radius:${isMine?'16px 4px 16px 16px':'4px 16px 16px 16px'};font-size:13.5px;line-height:1.5;word-break:break-word">${m.pesan||''}</div>
   184→                        <div style="font-size:10px;color:var(--text-muted);margin-top:3px;text-align:${isMine?'right':'left'}">${(m.created_at||'').toString().substring(11,16)}</div>
   185→                    </div>
   186→                </div>`;
   187→            }).join('');
   188→            el.scrollTop = el.scrollHeight;
   189→        });
   190→}
